import{_ as e,o as a,c as i,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"开启本地服务（LM Studio）","description":"LM Studio Local Server：监听地址、端口与 CORS，供手机 MiniTavern 经局域网 BYOK 连接。","frontmatter":{"title":"开启本地服务（LM Studio）","description":"LM Studio Local Server：监听地址、端口与 CORS，供手机 MiniTavern 经局域网 BYOK 连接。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"开启本地服务（LM Studio） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"LM Studio Local Server：监听地址、端口与 CORS，供手机 MiniTavern 经局域网 BYOK 连接。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/lmstudio/server"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/lmstudio/server"}]]},"headers":[],"relativePath":"lmstudio/server.md","filePath":"lmstudio/server.md","lastUpdated":1787117554000}'),o={name:"lmstudio/server.md"};function l(d,t,n,s,c,h){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="开启本地服务-lm-studio" tabindex="-1">开启本地服务（LM Studio） <a class="header-anchor" href="#开启本地服务-lm-studio" aria-label="Permalink to &quot;开启本地服务（LM Studio）&quot;">​</a></h1><h2 id="打开-local-server" tabindex="-1">打开 Local Server <a class="header-anchor" href="#打开-local-server" aria-label="Permalink to &quot;打开 Local Server&quot;">​</a></h2><ol><li>在 LM Studio 中打开 <strong>Local Server</strong>（或 Developer / 服务器）面板。</li><li>确认已加载要对外提供的模型。</li><li>开启服务器；记下界面上的：</li></ol><table tabindex="0"><thead><tr><th>项</th><th>常见默认</th></tr></thead><tbody><tr><td>端口</td><td><code>1234</code>（以你界面显示为准）</td></tr><tr><td>监听地址</td><td>需允许局域网（若有 <code>0.0.0.0</code> / 「允许网络中的设备访问」之类开关，请打开）</td></tr></tbody></table><ol start="4"><li>本机可先测：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:1234/v1/models</span></span></code></pre></div><p>浏览器或 <code>curl</code> 能看到模型列表即服务正常。</p><h2 id="局域网与防火墙" tabindex="-1">局域网与防火墙 <a class="header-anchor" href="#局域网与防火墙" aria-label="Permalink to &quot;局域网与防火墙&quot;">​</a></h2><ul><li>查电脑局域网 IP（见 <a href="./../quickstart#step-4查电脑局域网-ip">快速开始</a>）。</li><li>防火墙放行 LM Studio 使用的 TCP 端口（常见 <code>1234</code>）。</li><li>用另一台设备访问 <code>http://YOUR_PC_IP:1234/v1/models</code> 验证。</li></ul><h2 id="给-minitavern-用的地址" tabindex="-1">给 MiniTavern 用的地址 <a class="header-anchor" href="#给-minitavern-用的地址" aria-label="Permalink to &quot;给 MiniTavern 用的地址&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:1234/v1</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>Base URL</td><td>上一行地址</td></tr><tr><td>API Key</td><td>通常可留空或任意占位</td></tr><tr><td>模型名</td><td>与 Local Server 当前加载 / 列表中的 <strong>id</strong> 一致</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./../connect-app/minitavern">在 MiniTavern 中配置</a></p>',14)])])}const v=e(o,[["render",l]]);export{u as __pageData,v as default};
